impl From<u16> for Rust {
    #[inline]
    fn from(x: u16) -> Self {
        num_traits::FromPrimitive::from_u16(x).unwrap_or(Self::Error)
    }
}

// Rust == u16
impl PartialEq<u16> for Rust {
    #[inline]
    fn eq(&self, x: &u16) -> bool {
        *self == Into::<Self>::into(*x)
    }
}

// u16 == Rust
impl PartialEq<Rust> for u16 {
    #[inline]
    fn eq(&self, x: &Rust) -> bool {
        *x == *self
    }
}
